# Let me look at ALL tables with "bill" in the name in the document
import re

# Read the text file 
with open('/app/resources/treasury_bulletin_1953_03.txt', 'r') as f:
    content = f.read()

# Find all occurrences of "bill" in headers
lines = content.split('\n')
for i, line in enumerate(lines):
    if 'bill' in line.lower() and ('Table' in line or 'Taxable' in line or 'Amount' in line):
        print(f"Line {i}: {line[:100]}")

# Also search for 12/18 anywhere in the document
print("\n\nSearching for '12/18' anywhere in document:")
matches = []
for i, line in enumerate(lines):
    if '12/18' in line:
        matches.append((i, line[:200]))

if matches:
    for line_num, line in matches:
        print(f"Line {line_num}: {line}")
else:
    print("No matches found for 12/18")
EOF
